<?php
require __DIR__.'/app/bootstrap.php';
$slug=trim($_GET['slug']??'');$s=db()->prepare('SELECT * FROM brands WHERE slug=? AND is_active=1');$s->execute([$slug]);$brand=$s->fetch();if(!$brand){http_response_code(404);exit('Marka bulunamadı.');}
$s=db()->prepare('SELECT p.*,b.name brand_name,c.name category_name FROM products p LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN categories c ON c.id=p.category_id WHERE p.brand_id=? AND p.is_active=1 ORDER BY p.sales_count DESC,p.id DESC');$s->execute([(int)$brand['id']]);$products=$s->fetchAll();$pageTitle=$brand['name'].' Ürünleri | TOPLUCA';require __DIR__.'/includes/header.php';
?><section class="brand-hero"><div class="container"><small>MARKA</small><h1><?=h($brand['name'])?> Ürünleri</h1><p><?=h($brand['name'])?> ürünlerini uygun fiyat, hızlı teslimat ve TOPLUCA güvencesiyle keşfedin.</p></div></section><section class="section"><div class="container"><div class="toolbar"><strong><?=count($products)?> ürün</strong></div><div class="products-grid"><?php foreach($products as $p) require __DIR__.'/includes/product-card.php';?></div></div></section><?php require __DIR__.'/includes/footer.php';
